<div class="d-flex flex-wrap gap-2 mb-3"><?php if ($can_manage): ?><a class="btn btn-primary" href="<?= site_url('crews/'.$crew->crew_id.'/edit') ?>"><i class="bi bi-pencil" aria-hidden="true"></i> Edit Crew</a><a class="btn btn-success" href="<?= site_url('crews/'.$crew->crew_id.'/members/create') ?>"><i class="bi bi-person-plus" aria-hidden="true"></i> Add Member</a><?= form_open('crews/'.$crew->crew_id.'/status', array('class' => 'd-inline')) ?><button class="btn btn-outline-<?= $crew->is_active ? 'danger' : 'success' ?>" type="submit"><?= $crew->is_active ? 'Deactivate' : 'Activate' ?></button><?= form_close() ?><?php endif; ?><a class="btn btn-outline-secondary" href="<?= site_url('crews') ?>">Back to Crews</a></div>
<div class="row g-3 mb-4"><div class="col-lg-7"><div class="card shadow-sm h-100"><div class="card-header"><h2 class="card-title mb-0">Crew Header</h2></div><div class="card-body"><dl class="row mb-0"><dt class="col-sm-4">Code</dt><dd class="col-sm-8"><?= html_escape($crew->crew_code) ?></dd><dt class="col-sm-4">Name</dt><dd class="col-sm-8"><?= html_escape($crew->crew_name ?? '—') ?></dd><dt class="col-sm-4">Source trade</dt><dd class="col-sm-8"><?= html_escape($crew->source_trade ?? '—') ?></dd><dt class="col-sm-4">Status</dt><dd class="col-sm-8"><span class="badge text-bg-<?= $crew->is_active ? 'success' : 'secondary' ?>"><?= $crew->is_active ? 'Active' : 'Inactive' ?></span></dd><dt class="col-sm-4">Updated</dt><dd class="col-sm-8"><?= html_escape(date('d-M-Y h:i A', strtotime($crew->updated_at))) ?></dd></dl></div></div></div><div class="col-lg-5"><div class="card shadow-sm h-100"><div class="card-header"><h2 class="card-title mb-0">Calculated Daily Crew Cost</h2></div><div class="card-body"><div class="snapshot-value mb-2"><?= html_escape(($calculated_cost['currency'] ? $calculated_cost['currency'].' ' : '').number_format($calculated_cost['total'], 2)) ?></div><p class="text-body-secondary mb-0">Sum of member quantity × current governed labor total rate.</p><?php if ($calculated_cost['missing_rates']): ?><div class="alert alert-warning mt-3 mb-0"><?= number_format($calculated_cost['missing_rates']) ?> member craft(s) have no current rate and are excluded.</div><?php endif; ?></div></div></div></div>
<div class="card shadow-sm mb-4"><div class="card-header d-flex align-items-center"><h2 class="card-title mb-0">Crew Composition</h2><?php if ($can_manage): ?><a class="btn btn-success btn-sm ms-auto" href="<?= site_url('crews/'.$crew->crew_id.'/members/create') ?>">Add Member</a><?php endif; ?></div><div class="card-body"><div class="table-responsive"><table class="table table-striped align-middle w-100 master-data-table"><thead><tr><th>Labor Code</th><th>Labor Craft</th><th>Category</th><th>Source Role</th><th>Quantity</th><th>Current Labor Rate</th><th>Calculated Daily Cost</th><th>Labor Status</th><?php if ($can_manage): ?><th data-dt-order="disable">Action</th><?php endif; ?></tr></thead><tbody><?php foreach ($members as $member): ?><tr><td><a href="<?= site_url('labor/'.$member->labor_id) ?>"><?= html_escape($member->labor_code) ?></a></td><td><?= html_escape($member->labor_name) ?></td><td><?= html_escape($member->labor_category_name ?? '—') ?></td><td><?= html_escape($member->source_role_name ?? '—') ?></td><td><?= number_format($member->member_count, 4) ?></td><td><?= $member->total_with_admin_fee !== NULL ? html_escape(($member->currency_code ? $member->currency_code.' ' : '').number_format($member->total_with_admin_fee, 2)) : '—' ?></td><td><?= $member->calculated_daily_cost !== NULL ? html_escape(($member->currency_code ? $member->currency_code.' ' : '').number_format($member->calculated_daily_cost, 2)) : '—' ?></td><td><?= $member->labor_is_active ? 'Active' : 'Inactive' ?></td><?php if ($can_manage): ?><td><a class="btn btn-outline-primary btn-sm" href="<?= site_url('crews/'.$crew->crew_id.'/members/'.$member->crew_member_id.'/edit') ?>">Edit</a></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><p class="small text-body-secondary mb-0 mt-3">Member removal is not exposed because `crew_member` has no inactive flag and destructive SQL has not been authorized.</p></div></div>
<div class="card shadow-sm"><div class="card-header"><h2 class="card-title mb-0">Productivity Usage</h2></div><div class="card-body"><div class="table-responsive"><table class="table table-striped align-middle w-100 master-data-table"><thead><tr><th>Cost Code</th><th>Standard Item</th><th>Revision</th><th>Output</th><th>Duration</th><th>Hours</th><th>Source</th><th>Effective</th></tr></thead><tbody><?php foreach ($productivity_usages as $usage): ?><tr><td><?= html_escape($usage->enterprise_cost_code ?? '—') ?></td><td><?= html_escape($usage->standard_item_name) ?></td><td><?= html_escape($usage->revision_no) ?></td><td><?= $usage->output_quantity !== NULL ? number_format($usage->output_quantity, 6).' '.html_escape($usage->output_uom_code ?? '') : '—' ?></td><td><?= $usage->duration_quantity !== NULL ? number_format($usage->duration_quantity, 4).' '.html_escape($usage->duration_uom_code ?? '') : '—' ?></td><td><?= $usage->duration_hours !== NULL ? number_format($usage->duration_hours, 4) : '—' ?></td><td><?= html_escape($usage->productivity_source ?? '—') ?></td><td><?= $usage->effective_date ? html_escape(date('d-M-Y', strtotime($usage->effective_date))) : '—' ?></td></tr><?php endforeach; ?></tbody></table></div></div></div>
